import type { DoodlePath } from "./doodles.data";

/**
 * Renders hand-drawn doodle paths (generated by scripts/doodles/generate-doodles.mjs).
 * Outlines get class "ink" (the story draws them on with GSAP's DrawSVG), filled
 * shapes get class "paint" (faded in). Always decorative: the parent SVG is aria-hidden.
 */
export function Doodle({
  paths,
  className,
  stretch = false,
}: {
  paths: readonly DoodlePath[];
  className?: string;
  /** Keep line widths constant when the SVG is stretched (paw cards). */
  stretch?: boolean;
}) {
  return (
    <g className={className}>
      {paths.map((p, i) => (
        <path
          key={i}
          d={p.d}
          className={p.fill ? "paint" : "ink"}
          fill={p.fill ?? "none"}
          stroke={p.stroke}
          strokeWidth={p.strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          vectorEffect={stretch ? "non-scaling-stroke" : undefined}
          // Normalised length: drawing a line on/off is just stroke-dashoffset 1 → 0.
          pathLength={p.fill || stretch ? undefined : 1}
        />
      ))}
    </g>
  );
}

/** Several doodles in a row, each in its own group: e.g. fur strands that fly off one by one. */
export function DoodleSet({
  items,
  className,
}: {
  items: readonly (readonly DoodlePath[])[];
  className: string;
}) {
  return (
    <>
      {items.map((paths, i) => (
        <Doodle key={i} paths={paths} className={`${className} ${className}-${i + 1}`} />
      ))}
    </>
  );
}
